package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumID;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

// {attackStyle} -> the player's current combat style name (e.g. "Accurate", "Aggressive",
// "Defensive Casting"), or "None" if the equipped weapon has no notable style right now
// (e.g. nothing equipped). Ported from gearscape's own resolveAttackStyleIndex/
// buildAttackStyle/weaponTypeStyleNames, which mirror RuneLite core's own
// AttackStylesPlugin#updateAttackStyle/#getWeaponTypeStyles (package-private there, so not
// directly reusable) — looks the equipped weapon's style set up via
// EnumID.WEAPON_STYLES -> a per-style StructComposition -> ParamID.ATTACK_STYLE_NAME.
class AttackStyleLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{attackStyle\\}", Pattern.CASE_INSENSITIVE);
	private static final String NO_STYLE = "None";

	private final Client client;

	@Inject
	private AttackStyleLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		String style = buildAttackStyle(resolveAttackStyleIndex());
		return style == null ? NO_STYLE : style;
	}

	// COM_MODE is the 0-based index of the currently selected combat style among the
	// equipped weapon's own style set. Staves are the one wrinkle -- index 4 covers both
	// Casting and Defensive Casting, disambiguated by AUTOCAST_DEFMODE -- so this folds that
	// in, giving a single index that uniquely identifies the selected style slot even for
	// weapons like partisans where more than one slot shares the same displayed name.
	private int resolveAttackStyleIndex()
	{
		int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
		if (styleIndex == 4)
		{
			styleIndex += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}

		return styleIndex;
	}

	// Null if the resolved style is "Other" (no notable style, e.g. an empty weapon slot) or
	// the weapon type isn't in the style table at all.
	private String buildAttackStyle(int attackStyleIndex)
	{
		String[] styleNames = weaponTypeStyleNames(client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY));
		if (attackStyleIndex < 0 || attackStyleIndex >= styleNames.length)
		{
			return null;
		}

		return styleNames[attackStyleIndex];
	}

	// weaponType == -1 in EnumID.WEAPON_STYLES for a couple of weapon types RuneLite core
	// itself special-cases (blue moon spear, partisan) -- same fallback arrays
	// AttackStylesPlugin uses.
	private String[] weaponTypeStyleNames(int weaponType)
	{
		int weaponStyleEnumId = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponType);
		if (weaponStyleEnumId == -1)
		{
			if (weaponType == 22) // Blue moon spear
			{
				return new String[] {"Accurate", "Aggressive", null, "Defensive", "Casting", "Defensive Casting"};
			}

			if (weaponType == 30) // Partisan
			{
				return new String[] {"Accurate", "Aggressive", "Aggressive", "Defensive"};
			}

			return new String[0];
		}

		int[] weaponStyleStructs = client.getEnum(weaponStyleEnumId).getIntVals();
		String[] styleNames = new String[weaponStyleStructs.length];
		for (int i = 0; i < weaponStyleStructs.length; i++)
		{
			String name = client.getStructComposition(weaponStyleStructs[i]).getStringValue(ParamID.ATTACK_STYLE_NAME);
			if ("Other".equals(name))
			{
				continue; // Leave this slot null -- no notable style, matches AttackStylesPlugin.
			}

			// Index 5 reuses the "Defensive" label for a staff's defensive-casting mode.
			styleNames[i] = (i == 5 && "Defensive".equals(name)) ? "Defensive Casting" : name;
		}

		return styleNames;
	}
}

package com.groundmarkervariables.variables;

import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// {<cond1> [&& or || <cond2>] ? <whenTrue> : <whenFalse>} — each <condN> is
// "<expr> [<cmp> <value>]": <cmp>/<value> are optional, so a bare <expr> (e.g. hasThralls)
// evaluates its own resolved value directly as a "true"/"false" boolean. <cmp> is one of
// == != < > <= >=. <expr> is any other variable's own body (no surrounding braces), e.g.
// "spellbook" or "metronome5_2". Evaluated by re-wrapping <expr> in braces and testing it
// against every VariableRegistry variable's own pattern(), so this works for any current or
// future variable without changes here. == and != are always a case-insensitive string
// (in)equality check; the ordering comparators require both sides to parse as numbers
// (metronome's countdown is the only numeric variable today, but nothing here is
// metronome-specific) and are otherwise unresolvable, same as an unresolvable <expr>.
//
// && / || combine exactly two conditions (not an arbitrary chain — see PATTERN) using
// three-valued logic: an unresolvable side still settles the result if the other side
// already does (false && anything = false, true || anything = true); otherwise the whole
// conditional is left untouched rather than silently picking a branch.
//
// [^{}]+? (not .+?) in every group deliberately stops this from matching at all if an
// <expr>, <value>, or a branch contains its own '{'/'}' — nested variables inside a
// conditional aren't supported (regex can't parse nested braces), so this fails safe by
// leaving the whole expression untouched rather than mis-parsing it. The same non-greedy
// stopping means a third chained &&/|| (not just two conditions) won't parse as intended
// either — the second <expr> just swallows the rest as an unresolvable blob.
//
// The two branch groups are the one deliberate exception: they also allow a literal
// {metronomeN} / {metronomeN_M} token, or its {mN} / {mN_M} alias, specifically
// (METRONOME_TOKEN), so a branch containing one doesn't just make the whole conditional fail
// to match. Without this, the branch's braces would still be sitting in the label text
// untouched, and MetronomeLabelVariable's own later, independent pass (see LabelResolver)
// would resolve it anyway — the conditional would visibly fail to pick a branch, but the
// metronome number would still render. resolve() neutralizes any such token in the winning
// branch to the bare word "metronome" (see METRONOME_TOKEN_PATTERN), so it's fully inert
// here, matching every other way metronome is blocked from conditional use (see
// VariableRegistry for <expr>).
class ConditionalVariable implements LabelVariable
{
	private static final String METRONOME_TOKEN = "(?i:\\{(?:metronome|m)\\d+(?:_\\d+)?\\})";
	private static final Pattern METRONOME_TOKEN_PATTERN = Pattern.compile(METRONOME_TOKEN);
	private static final String BRANCH = "(?:[^{}]|" + METRONOME_TOKEN + ")+?";

	private static final String CONDITION = "([^{}]+?)\\s*(?:(==|!=|<=|>=|<|>)\\s*([^{}]+?)\\s*)?";
	private static final Pattern PATTERN = Pattern.compile(
		"\\{\\s*" + CONDITION + "(?:(&&|\\|\\|)\\s*" + CONDITION + ")?\\?\\s*(" + BRANCH + ")\\s*:\\s*(" + BRANCH + ")\\s*\\}");

	private final List<LabelVariable> variables;

	@Inject
	private ConditionalVariable(VariableRegistry registry)
	{
		this.variables = registry.all();
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		Boolean result = evaluateCondition(matcher.group(1), matcher.group(2), matcher.group(3));

		String logicOp = matcher.group(4);
		if (logicOp != null)
		{
			Boolean second = evaluateCondition(matcher.group(5), matcher.group(6), matcher.group(7));
			result = "&&".equals(logicOp) ? and(result, second) : or(result, second);
		}

		if (result == null)
		{
			return null;
		}

		String winner = result ? matcher.group(8) : matcher.group(9);
		return METRONOME_TOKEN_PATTERN.matcher(winner).replaceAll("ILLEGAL");
	}

	private Boolean evaluateCondition(String expr, String comparator, String expected)
	{
		String actual = resolveExpression(expr);
		return actual == null ? null : evaluate(actual, comparator, expected);
	}

	private String resolveExpression(String expr)
	{
		for (LabelVariable variable : variables)
		{
			Matcher wrapped = variable.pattern().matcher("{" + expr + "}");
			if (wrapped.matches())
			{
				return variable.resolve(wrapped);
			}
		}

		return null;
	}

	// Null means "can't be evaluated" (e.g. an ordering comparator against a non-numeric
	// value like a player name), distinct from false, so resolve() can leave the whole
	// conditional untouched rather than silently picking a branch for an unanswerable check.
	private static Boolean evaluate(String actual, String comparator, String expected)
	{
		if (comparator == null)
		{
			return tryParseBoolean(actual);
		}

		if ("==".equals(comparator))
		{
			return actual.equalsIgnoreCase(expected);
		}

		if ("!=".equals(comparator))
		{
			return !actual.equalsIgnoreCase(expected);
		}

		Double actualNum = tryParseNumber(actual);
		Double expectedNum = tryParseNumber(expected);
		if (actualNum == null || expectedNum == null)
		{
			return null;
		}

		switch (comparator)
		{
			case "<":
				return actualNum < expectedNum;
			case ">":
				return actualNum > expectedNum;
			case "<=":
				return actualNum <= expectedNum;
			case ">=":
				return actualNum >= expectedNum;
			default:
				return null;
		}
	}

	// Three-valued AND: false wins regardless of the other side (even if unresolvable);
	// otherwise null propagates unless both sides are known true.
	private static Boolean and(Boolean a, Boolean b)
	{
		if (Boolean.FALSE.equals(a) || Boolean.FALSE.equals(b))
		{
			return Boolean.FALSE;
		}

		return (a == null || b == null) ? null : Boolean.TRUE;
	}

	// Three-valued OR: true wins regardless of the other side; otherwise null propagates
	// unless both sides are known false.
	private static Boolean or(Boolean a, Boolean b)
	{
		if (Boolean.TRUE.equals(a) || Boolean.TRUE.equals(b))
		{
			return Boolean.TRUE;
		}

		return (a == null || b == null) ? null : Boolean.FALSE;
	}

	private static Double tryParseNumber(String value)
	{
		try
		{
			return Double.parseDouble(value);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	// Strict on purpose: a non-boolean variable used bare (e.g. {spellbook ? A : B}) should
	// be unresolvable, not silently treated as false.
	private static Boolean tryParseBoolean(String value)
	{
		if ("true".equalsIgnoreCase(value))
		{
			return Boolean.TRUE;
		}

		if ("false".equalsIgnoreCase(value))
		{
			return Boolean.FALSE;
		}

		return null;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

// A {token} substitution ground marker labels can use, e.g. {rsn} or {metronome5}. A regex
// rather than a literal string because some variables carry their own parameters (the "5"
// in {metronome5}) that resolve() needs to read back out of the match via capture groups.
public interface LabelVariable
{
	// Matches every occurrence of this variable in a label, e.g. Pattern.compile("\\{rsn\\}").
	Pattern pattern();

	// Given a match against pattern(), the text to substitute in its place, or null if it
	// can't be resolved right now (e.g. not logged in yet) — the match is then left as-is.
	String resolve(Matcher matcher);
}

package com.groundmarkervariables.variables;

import net.runelite.api.Skill;

// Shared "<skill> text -> Skill enum" lookup for any variable keyed by skill name (e.g.
// {lvl_<skill>}, {boost_<skill>}). Matches Skill.getName() case-insensitively.
final class SkillFinder
{
	private SkillFinder()
	{
	}

	static Skill find(String name)
	{
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(name))
			{
				return skill;
			}
		}

		return null;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;

// {lvl_<skill>} -> the player's real (unboosted) level in <skill>, e.g. {lvl_attack},
// {lvl_hitpoints}, {lvl_mining}. <skill> matches any Skill.getName() case-insensitively, so
// {lvl_Runecraft} and {lvl_RUNECRAFT} both work same as {lvl_runecraft}. Uses
// getRealSkillLevel(), not getBoostedSkillLevel() — potion/prayer boosts don't affect it.
class SkillLevelLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{lvl_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;

	@Inject
	private SkillLevelLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		return skill == null ? null : String.valueOf(client.getRealSkillLevel(skill));
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

// {hasFreeze} — true if the player could freeze someone right now, via either path:
//  - Ancient Magicks spellbook + enough runes for Ice Barrage (6 water, 2 blood, 4 death —
//    the strongest/most commonly used ice spell, not the cheapest; RuneCounter accounts for
//    an infinite-water-rune weapon, but blood/death have no infinite source in the game), or
//  - a Blighted ancient ice sack (acts like the runes for any ice spell) while in the
//    Wilderness.
// Doesn't check Magic level (94 for Ice Barrage) — same convention as hasThralls, only what
// was explicitly asked for.
class HasFreezeLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{hasFreeze\\}", Pattern.CASE_INSENSITIVE);
	private static final int ANCIENT_SPELLBOOK = 1;

	private final Client client;

	@Inject
	private HasFreezeLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		boolean hasFreeze = (onAncientSpellbook() && hasIceBarrageRunes())
			|| (hasBlightedIceSack() && inWilderness());

		return String.valueOf(hasFreeze);
	}

	private boolean onAncientSpellbook()
	{
		return client.getVarbitValue(VarbitID.SPELLBOOK) == ANCIENT_SPELLBOOK;
	}

	private boolean hasIceBarrageRunes()
	{
		return RuneCounter.hasAtLeast(client, ItemID.WATERRUNE, 6)
			&& RuneCounter.hasAtLeast(client, ItemID.BLOODRUNE, 2)
			&& RuneCounter.hasAtLeast(client, ItemID.DEATHRUNE, 4);
	}

	private boolean hasBlightedIceSack()
	{
		return RuneCounter.itemCount(client, InventoryID.INVENTORY, ItemID.BLIGHTED_SACK_ICEBARRAGE) > 0;
	}

	private boolean inWilderness()
	{
		return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) != 0;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

// {hasThralls} — true only while the player could cast an Arceuus Conjure spell right now:
// Arceuus spellbook active, Book of the Dead owned (equipped or carried), and at least one
// fire, blood, and cosmic rune available (RuneCounter — inventory + rune pouch, plus an
// infinite source for fire). Doesn't check Magic level.
class HasThrallsLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{hasThralls\\}", Pattern.CASE_INSENSITIVE);
	private static final int ARCEUUS_SPELLBOOK = 3;

	private final Client client;

	@Inject
	private HasThrallsLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		boolean hasThralls = client.getVarbitValue(VarbitID.SPELLBOOK) == ARCEUUS_SPELLBOOK
			&& hasBookOfTheDead()
			&& RuneCounter.hasAtLeast(client, ItemID.FIRERUNE, 1)
			&& RuneCounter.hasAtLeast(client, ItemID.BLOODRUNE, 1)
			&& RuneCounter.hasAtLeast(client, ItemID.COSMICRUNE, 1);

		return String.valueOf(hasThralls);
	}

	private boolean hasBookOfTheDead()
	{
		return RuneCounter.itemCount(client, InventoryID.INVENTORY, ItemID.BOOK_OF_THE_DEAD) > 0
			|| RuneCounter.itemCount(client, InventoryID.EQUIPMENT, ItemID.BOOK_OF_THE_DEAD) > 0;
	}
}

package com.groundmarkervariables.variables;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

// {hasItem <name>} -> "true" if the player currently holds an item whose ItemComposition name
// contains <name> (case-insensitive substring, not exact match — e.g. {hasItem rune} matches
// "Rune pouch", "Air rune", "Runite ore", ...) in their inventory or equipment, "false"
// otherwise. <name> is everything after "hasItem " up to the closing brace.
//
// Also checks a rune pouch's contents (any variant: regular/looted, divine/looted), but only
// when the pouch itself is actually in the inventory — same rune/quantity varbits and
// EnumID.RUNEPOUCH_RUNE lookup core's own RunepouchOverlay uses.
//
// [^{}?:]+? (not [^{}]+?) deliberately excludes '?' and ':' from <name>, the same fail-safe
// philosophy ConditionalVariable uses excluding '{'/'}' from its own groups: this variable is
// itself a registered base variable, so LabelResolver's own pass over it runs before
// ConditionalVariable's does. Without the exclusion, {hasItem staff of the dead ? A : B} used
// as a bare conditional <expr> would match THIS pattern directly first and swallow "? A : B"
// as part of the item name, resolving to false before the conditional ever got a turn. No
// real item name contains '?' or ':', so this costs nothing in practice.
class HasItemLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{hasItem\\s+([^{}?:]+?)\\s*\\}", Pattern.CASE_INSENSITIVE);

	private static final int[] RUNE_POUCH_ITEM_IDS = {
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER
	};
	private static final int[] RUNE_POUCH_AMOUNT_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};

	private final Client client;
	private final ItemManager itemManager;

	@Inject
	private HasItemLabelVariable(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		String search = matcher.group(1).toLowerCase(Locale.ROOT);
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		boolean hasItem = containerHasItemContaining(inventory, search)
			|| containerHasItemContaining(client.getItemContainer(InventoryID.EQUIPMENT), search)
			|| (inventoryHasRunePouch(inventory) && runePouchContains(search));
		return String.valueOf(hasItem);
	}

	private boolean containerHasItemContaining(ItemContainer container, String search)
	{
		if (container == null)
		{
			return false;
		}

		for (Item item : container.getItems())
		{
			// Empty slots are Items with id <= 0 (typically -1), not null array elements.
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}

			String name = itemManager.getItemComposition(item.getId()).getName().toLowerCase(Locale.ROOT);
			if (name.contains(search))
			{
				return true;
			}
		}

		return false;
	}

	private boolean inventoryHasRunePouch(ItemContainer inventory)
	{
		if (inventory == null)
		{
			return false;
		}

		for (Item item : inventory.getItems())
		{
			if (item == null)
			{
				continue;
			}

			for (int runePouchId : RUNE_POUCH_ITEM_IDS)
			{
				if (item.getId() == runePouchId)
				{
					return true;
				}
			}
		}

		return false;
	}

	private boolean runePouchContains(String search)
	{
		EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		for (int i = 0; i < RUNE_POUCH_AMOUNT_VARBITS.length; i++)
		{
			int amount = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			int runeType = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			if (amount <= 0 || runeType == 0)
			{
				continue;
			}

			String name = itemManager.getItemComposition(runepouchEnum.getIntValue(runeType)).getName().toLowerCase(Locale.ROOT);
			if (name.contains(search))
			{
				return true;
			}
		}

		return false;
	}
}

