package com.groundmarkervariables.variables;

import java.util.List;
import javax.inject.Inject;

// The "base" value-producing variables — the ones ConditionalVariable evaluates the
// left-hand side of a comparison against. Kept separate from LabelResolver's own list
// (which also includes ConditionalVariable itself) so ConditionalVariable can depend on
// this registry instead of on LabelResolver, avoiding a circular dependency.
//
// MetronomeLabelVariable is deliberately NOT here — see LabelResolver's comment for why it's
// excluded from conditional support entirely (both as <expr> and inside A/B branches).
class VariableRegistry
{
	private final List<LabelVariable> variables;

	@Inject
	private VariableRegistry(
		RsnLabelVariable rsn,
		SpellbookLabelVariable spellbook,
		HasThrallsLabelVariable hasThralls,
		WeaponLabelVariable weapon,
		SkillLevelLabelVariable skillLevel,
		HasFreezeLabelVariable hasFreeze,
		HasEntangleLabelVariable hasEntangle,
		BoostedSkillLevelLabelVariable boostedSkillLevel,
		AttackStyleLabelVariable attackStyle,
		HasItemLabelVariable hasItem,
		MiscellaniaLabelVariable miscellania,
		HasAlchsLabelVariable hasAlchs)
	{
		this.variables = List.of(
			rsn, spellbook, hasThralls, weapon, skillLevel, hasFreeze, hasEntangle, boostedSkillLevel,
			attackStyle, hasItem, miscellania, hasAlchs);
	}

	List<LabelVariable> all()
	{
		return variables;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.InventoryID;
import net.runelite.client.game.ItemManager;

// {weapon} -> the equipped weapon's item name (e.g. "Abyssal whip"), or "Unarmed" if the
// weapon slot is empty.
class WeaponLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{weapon\\}", Pattern.CASE_INSENSITIVE);
	private static final String UNARMED = "Unarmed";

	private final Client client;
	private final ItemManager itemManager;

	@Inject
	private WeaponLabelVariable(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return UNARMED;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null || weapon.getId() <= 0)
		{
			return UNARMED;
		}

		return itemManager.getItemComposition(weapon.getId()).getName();
	}
}

package com.groundmarkervariables.variables;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import javax.inject.Inject;

// Applies every registered LabelVariable to a marker's label. To add a new base variable
// (one usable directly and inside a {expr == value ? a : b} conditional): write a
// LabelVariable implementation and add it to VariableRegistry — nothing here needs to
// change. ConditionalVariable itself is listed separately since it depends on that same
// registry (see VariableRegistry's comment for why).
//
// MetronomeLabelVariable is listed separately too, deliberately LAST (after conditional)
// Per Plugin Hub review, metronomes inside of conditionals are too risky for abuse.
public class LabelResolver
{
	private final List<LabelVariable> variables;

	@Inject
	private LabelResolver(VariableRegistry registry, ConditionalVariable conditional, MetronomeLabelVariable metronome)
	{
		List<LabelVariable> all = new ArrayList<>(registry.all());
		all.add(conditional);
		all.add(metronome);
		this.variables = List.copyOf(all);
	}

	public String resolve(String label)
	{
		if (label == null)
		{
			return null;
		}

		String resolved = label;
		for (LabelVariable variable : variables)
		{
			Matcher matcher = variable.pattern().matcher(resolved);
			StringBuilder replaced = new StringBuilder();
			while (matcher.find())
			{
				String value = variable.resolve(matcher);
				if (value != null)
				{
					matcher.appendReplacement(replaced, Matcher.quoteReplacement(value));
				}
			}
			matcher.appendTail(replaced);
			resolved = replaced.toString();
		}

		return resolved;
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;

// {boost_<skill>} -> the player's current boosted (post potion/prayer/curse) level in
// <skill>, e.g. {boost_attack}, {boost_hitpoints}, {boost_mining}. <skill> matches any
// Skill.getName() case-insensitively, same as {lvl_<skill>}. Uses getBoostedSkillLevel(),
// not getRealSkillLevel() — the opposite of SkillLevelLabelVariable.
class BoostedSkillLevelLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{boost_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;

	@Inject
	private BoostedSkillLevelLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolve(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		return skill == null ? null : String.valueOf(client.getBoostedSkillLevel(skill));
	}
}

package com.groundmarkervariables;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

// Standard color names usable as <col=NAME>, e.g. <col=red> — expanded to <col=FF0000> at
// render time (see GroundMarkerVariablesOverlay) and offered as autocomplete candidates once
// "<col=" has been typed (see AdvancedLabelEditor).
final class NamedColors
{
	static final Map<String, String> HEX_BY_NAME = createHexByName();

	private NamedColors()
	{
	}

	private static Map<String, String> createHexByName()
	{
		Map<String, String> colors = new LinkedHashMap<>();
		colors.put("red", "FF0000");
		colors.put("green", "00FF00");
		colors.put("blue", "0000FF");
		colors.put("teal", "00FFFF");
		colors.put("yellow", "FFFF00");
		colors.put("purple", "FF00FF");
		colors.put("white", "FFFFFF");
		colors.put("black", "000000");
		return Collections.unmodifiableMap(colors);
	}
}

